(function(){const frame=document.getElementById('plasma-x-timeline');if(!frame)return;const source='<!doctype html><html lang="en"><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body{margin:0;padding:0;width:100%;min-height:100%;background:#191120;color:#e0d5e8;font:16px/1.5 Arial,sans-serif}a{color:#cfb0ed}.twitter-timeline{display:block!important;width:100%!important;max-width:none!important;margin:0!important;border:0!important}p{padding:16px}</style></head><body><a class="twitter-timeline" data-theme="dark" data-chrome="nofooter noborders" data-dnt="true" data-height="'+Math.max(200,window.innerHeight)+'" href="https://twitter.com/plasma1337x">Posts by @plasma1337x</a><script async src="https://platform.twitter.com/widgets.js" charset="utf-8" onerror="document.getElementById(\'unavailable\').hidden=false"><\/script><p id="unavailable" hidden>X could not load the feed. Try reloading it.</p></body></html>';const load=()=>{frame.srcdoc=source};load();})();
